import json, os
base='bench/results/2026-10-12/m1-ngram/replay/'
PHASES=["single-agent","single-mem","dual-agent","dual-mem"]
ROLE={"single-agent":"agent","single-mem":"mem","dual-agent":"agent","dual-mem":"mem"}
def load(a):
    p=os.path.join(base,a,"requests.jsonl")
    if not os.path.exists(p): return None
    return [json.loads(l) for l in open(p) if l.strip()]
arms={"off":load("off-greedy"),"offP":load("off-prod"),"A":load("A-greedy"),"AP":load("A-prod"),"B":load("B-greedy"),"BP":None}
print("arms loaded:", [a for a in arms if arms[a]])
# --- identity rates (greedy) from shas, fg only ---
def fg_sha_map(d, phase):
    return {(r['id']): r['out_sha256'] for r in d if r.get('fg_bg')=='fg' and r['phase']==phase}
def cmp_arm(specD, offD):
    # specD and offD are same-phase lists? No: use same phase
    pass
def per_phase_identity(spec_name, off_name, phase, spec_rows, off_rows, spec_outputs=None):
    # spec_rows for this phase fg; off_rows for this phase fg
    spec_fg=[r for r in spec_rows if r['phase']==phase and r['fg_bg']=='fg']
    off_map={r['id']:r['out_sha256'] for r in off_rows if r['phase']==phase and r['fg_bg']=='fg'}
    same=mism=0; diverg=[]
    for r in spec_fg:
        o=off_map.get(r['id'])
        if o is None: continue
        if r['out_sha256']==o: same+=1
        else:
            mism+=1
            # first divergence from outputs if available
    return same, mism, len(spec_fg)
print("\n=== GREEDY identity (fg rows, same phase+id) vs off-greedy ===")
print("phase        A same/total   B same/total")
for ph in PHASES:
    A=per_phase_identity('A','off',ph,load("A-greedy"),load("off-greedy"))
    B=per_phase_identity('B','off',ph,load("B-greedy"),load("off-greedy"))
    print(f"{ph:<12} A {A[0]}/{A[2]}     B {B[0]}/{B[2]}")
